/**
 * 表示用于流体容器方块（如炼药锅）中的流体类型。
 */
export enum FluidType {
    /**
     * @remarks
     * 表示熔岩作为一种流体类型。
     *
     */
    Lava = 'Lava',
    /**
     * @remarks
     * 表示药水作为一种流体类型。
     *
     */
    Potion = 'Potion',
    /**
     * @remarks
     * 表示细雪作为一种流体类型。
     *
     */
    PowderSnow = 'PowderSnow',
    /**
     * @remarks
     * 表示水作为一种流体类型。
     *
     */
    Water = 'Water',
}